/* Regio and Local trains arrive as timetable patterns (stops, minutes from the start, start times); expand them into
   one train per departure. Labels: "RS 37" / "RX 37" for Regio, the line letter ("A1") for Local. */
if(typeof RR_PATTERNS!=='undefined')for(const p of RR_PATTERNS){const label=p.type==='Local'?(p.pat==='S'?p.line:p.line.replace(/\d+/g,'')):p.pat+' '+p.line,plat=String(p.dir),platforms=Object.fromEntries(p.stops.map(n=>[n,plat]));
 for(const s0 of p.starts){const hh=Math.floor(s0/60)%24,tm=m=>{const d=Math.floor(m/1440),x=m%1440;return String(Math.floor(x/60)).padStart(2,'0')+':'+String(x%60).padStart(2,'0')+(d?' +'+d:'')},route=p.stops.map((n,i)=>[n,tm(s0+p.off[i])]);
  TRAINS.push({id:`${p.type==='Local'?p.line:label}·${p.code}-${p.dir}${String(hh).padStart(2,'0')}${p.type==='Local'?String(s0%60).padStart(2,'0'):''}`,label,dir:p.dir,hh,type:p.type,pattern:p.type==='Regio'?p.pat:undefined,line:p.line,network:p.net,origin:route[0][0],dest:route[route.length-1][0],route,plat,status:'On time',stock:p.stock,fac:p.fac,platforms})}}
/* Daily operations. The timetable is identical every day; what changes is
   the day's running: delays, cancellations and platform alterations. They are
   drawn from a seed made of the viewer's local date, so every visitor sees the
   same disruption on the same day and a new pattern tomorrow. Delays only show
   for trains that are running or due to leave soon, as they would on a real
   information screen. */
